#include <bits/stdc++.h>
#include <vector>
#include <algorithm>

using namespace std;
long long slove(long long x){
    if(x <= 1)
            return 0;
    long long sum = 0;
    for(long long i = 1; i <= sqrt(x); i++){
        if(x % i == 0){
            if(i != x/i)
                sum += i + x/i;
            else
                sum += i;
        }
    }
    return (sum-x);
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long n;
    cin >> n;
    if(slove(n)==n)
        cout<<"YES";
    else
        cout<<"NO";
    return 0;
}
